package com.constructionpilot;

import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;

// Build and remove clicks with their tick timing, and how fast you build.
// Measured: the Build click only opens the menu; planks go about a tick after the menu closes and the
// furniture appears a tick after that. A Remove click clears the space on the next tick.
@Singleton
class BuildTimer
{
	private static final int DEFAULT_BUILD_TICKS = 1;
	// Until enough builds are measured: about one plank per tick.
	private static final double DEFAULT_PLANKS_PER_TICK = 1.0;
	// From the menu closing, the build counts as done until its planks are taken.
	private static final int BUILD_COMMIT_TICKS = 2;
	// A build menu closing this long after the click is not that build's menu.
	private static final int BUILD_MENU_TICKS = 30;
	// A build that never produced furniture (cancelled menu, not enough planks) expires.
	private static final int PENDING_TICKS = 8;
	// A remove click that has not cleared the space by then (dialog closed, misclick) is dropped.
	private static final int REMOVE_CLICK_TICKS = 3;
	// The other side is the tick-optimal build only right after a remove.
	private static final int FRESH_REMOVE_TICKS = 3;
	// Longer gaps are breaks or butler waits, not your building rhythm.
	private static final int MAX_BUILD_GAP = 12;

	private final Client client;
	private final House house;
	private final TickLog tickLog;

	@Getter
	private double planksPerTick = DEFAULT_PLANKS_PER_TICK;
	private final RollingMedian buildGaps = new RollingMedian(8);
	private int lastBuildTick = -1;
	private int buildTicks = DEFAULT_BUILD_TICKS;

	// The hotspot the last Build click went to, so the countdown follows the side actually built.
	private WorldPoint buildClickTile;
	private int buildClickTick = -1;
	private int buildCommitTick = -1;
	private int planksAtBuildCommit = -1;
	private List<WorldPoint> pendingBuild;
	private int pendingBuildTick = -1;

	private String removingKey;
	private int removeClickTick = -1;
	private String lastRemovedKey;
	private int lastRemovedTick = -1;

	@Inject
	BuildTimer(Client client, House house, TickLog tickLog)
	{
		this.client = client;
		this.house = house;
		this.tickLog = tickLog;
	}

	void reset()
	{
		buildGaps.clear();
		lastBuildTick = -1;
		pendingBuild = null;
	}

	void clicked(String option, WorldPoint tile)
	{
		if ("Build".equals(option))
		{
			buildClickTile = tile;
			buildClickTick = client.getTickCount();
		}
		else if ("Remove".equals(option))
		{
			removingKey = house.spaceAt(tile);
			removeClickTick = client.getTickCount();
		}
		else
		{
			// Talking to the butler (or anything else) breaks the tick rhythm, so either empty side is fine again.
			lastRemovedTick = -1;
		}
	}

	void buildMenuClosed(int planks)
	{
		// A cancel simply never takes planks.
		if (buildClickTick >= 0 && client.getTickCount() - buildClickTick <= BUILD_MENU_TICKS)
		{
			buildCommitTick = client.getTickCount();
			planksAtBuildCommit = planks;
		}
	}

	void planksUsed(int before, int now, int perBuild)
	{
		if (before - now != perBuild)
		{
			return;
		}
		recordBuild(perBuild);
		List<WorldPoint> built = clickedSpace();
		if (built != null)
		{
			pendingBuild = built;
			pendingBuildTick = client.getTickCount();
		}
	}

	void furnitureAppeared(GameObject object)
	{
		if (pendingBuild != null && pendingBuild.contains(object.getWorldLocation()))
		{
			int took = client.getTickCount() - pendingBuildTick;
			if (took >= 0 && took <= 4)
			{
				buildTicks = took;
			}
			pendingBuild = null;
			tickLog.add("built after " + took + " ticks");
		}
	}

	void furnitureGone(GameObject object)
	{
		lastRemovedKey = house.spaceAt(object.getWorldLocation());
		lastRemovedTick = client.getTickCount();
		removingKey = null;
	}

	void tick()
	{
		if (pendingBuild != null && client.getTickCount() - pendingBuildTick > PENDING_TICKS)
		{
			pendingBuild = null;
		}
	}

	boolean isPending()
	{
		return pendingBuild != null;
	}

	// Fills in the build side of the snapshot. Between the menu closing and the planks going, the build already
	// counts: its planks as spent and its space as appearing.
	Snapshot.SnapshotBuilder describe(Snapshot.SnapshotBuilder snapshot, int planks, int perBuild)
	{
		int now = client.getTickCount();
		List<WorldPoint> inFlight = pendingBuild == null && buildCommitTick >= 0
			&& now - buildCommitTick <= BUILD_COMMIT_TICKS
			&& planks == planksAtBuildCommit && planks >= perBuild ? clickedSpace() : null;
		return snapshot
			.planks(inFlight != null ? planks - perBuild : planks)
			.planksPerTick(planksPerTick)
			.pendingBuild(inFlight != null ? inFlight : pendingBuild)
			.ticksUntilBuilt(inFlight != null ? buildTicks + 1 - (now - buildCommitTick) : pendingBuild == null ? 0 : buildTicks - (now - pendingBuildTick))
			.removing(removingKey != null && now - removeClickTick <= REMOVE_CLICK_TICKS ? removingKey : null)
			.freshRemoved(lastRemovedTick >= 0 && now - lastRemovedTick <= FRESH_REMOVE_TICKS ? lastRemovedKey : null);
	}

	private List<WorldPoint> clickedSpace()
	{
		return client.getLocalPlayer() == null ? null : house.spaceTiles(buildClickTile, client.getLocalPlayer().getWorldLocation());
	}

	// Plank use from the median gap between recent builds; breaks and butler waits do not drag it down.
	private void recordBuild(int perBuild)
	{
		int tick = client.getTickCount();
		int gap = tick - lastBuildTick;
		if (lastBuildTick >= 0 && gap > 0 && gap <= MAX_BUILD_GAP)
		{
			planksPerTick = (double) perBuild / buildGaps.add(gap);
		}
		lastBuildTick = tick;
	}
}

package com.constructionpilot;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

// The servant: where he is, his bank trips, what he holds and what he costs.
@Singleton
class Butler
{
	// Farther than this he is too far to click without walking; treat him as gone.
	private static final int REACH = 6;
	// He hands over only once you are free; past this the hand-over is not coming (empty bank).
	private static final int HAND_OVER_TICKS = 30;
	// Servant dialogue, as read by the Butler Info plugin.
	private static final Pattern WAITS_WITH = Pattern.compile("I shall wait with these (\\d+) items");
	private static final String WAITS_WITH_LAST = "I shall wait with the last item";
	private static final String RETURNED_ALL = "Master, I have returned with what you asked me to retrieve.";
	private static final String RETURNED = "I have returned with what";
	private static final String SENT_BACK = "Take them back to the bank";
	private static final String PAID_BY_HAND = "Okay, here's";
	private static final String PAID_FROM_BAG = "Your servant takes some payment from the money bag.";
	private static final Pattern FETCH_OPTION = Pattern.compile("^Fetch from bank: (\\d+) x");

	private final Client client;
	private final TickLog tickLog;
	private final House house;

	@Getter
	private NPC npc;
	@Getter
	private ServantType type;
	@Getter
	private int holding;
	@Getter
	private int lastDelivery;
	// From the "Repeat last task?" option; 0 until seen.
	@Getter
	private int requestedFetch;
	// His return message is open: continuing it makes him walk off, clicking the next spot keeps him next to you.
	@Getter
	private boolean returnDialogOpen;
	// Unknown (-1) until the first wage payment is seen.
	@Getter
	private int tripsUntilPay = -1;
	@Getter
	private int wagesPaid;
	// Set when you pay him by hand, cleared when the money bag pays.
	@Getter
	private boolean paidByHand;

	private boolean awaitingHandOver;
	private int arrivedTick = -1;
	private int leftTick = -1;
	// Planks arriving on the tick of his return dialogue or the next are still the delivery.
	private int handOverTick = -1;
	private final RollingMedian recentTrips = new RollingMedian(5);
	private int measuredTripTicks = -1;
	private long lastTickMillis;
	private String lastOptions = "";

	@Inject
	Butler(Client client, TickLog tickLog, House house)
	{
		this.client = client;
		this.tickLog = tickLog;
		this.house = house;
	}

	void reset()
	{
		npc = null;
		holding = 0;
		leftTick = -1;
		returnDialogOpen = false;
	}

	void spawned(NPC spawned, WorldPoint player)
	{
		ServantType spawnedType = ServantType.byNpcId(spawned.getId());
		if (spawnedType == null)
		{
			return;
		}
		npc = spawned;
		type = spawnedType;
		arrivedTick = client.getTickCount();
		awaitingHandOver = leftTick >= 0;
		if (leftTick >= 0)
		{
			int trip = arrivedTick - leftTick;
			// A despawn without a bank trip (dismissed, room reload) is far off the servant's trip time.
			if (trip >= type.getTripTicks() - 3 && trip <= type.getTripTicks() + 8)
			{
				measuredTripTicks = recentTrips.add(trip);
			}
			tickLog.add("trip took " + trip + " ticks");
		}
		if (tickLog.enabled())
		{
			WorldPoint at = spawned.getWorldLocation();
			String relative = player == null ? "?" : "dx=" + (at.getX() - player.getX()) + " dy=" + (at.getY() - player.getY());
			tickLog.add(type.getName() + " arrives at " + at + " player " + player + " " + relative + (house.isSpace(at) ? " ON " + house.spaceAt(at) : ""));
		}
	}

	void despawned(NPC despawned)
	{
		if (despawned != npc)
		{
			return;
		}
		npc = null;
		holding = 0;
		leftTick = client.getTickCount();
		if (tripsUntilPay > 0)
		{
			tripsUntilPay--;
		}
		tickLog.add("butler leaves");
	}

	// The hand-over after a trip is a delivery; taking leftovers later only empties his hands.
	void planksGained(int gained)
	{
		if (npc == null)
		{
			return;
		}
		if (awaitingHandOver || client.getTickCount() - handOverTick <= 1)
		{
			lastDelivery = gained;
			awaitingHandOver = false;
		}
		else if (holding > 0)
		{
			holding = Math.max(0, holding - gained);
		}
	}

	void dialog(String text)
	{
		if (text.contains(RETURNED))
		{
			returnDialogOpen = true;
		}
		Matcher waits = WAITS_WITH.matcher(text);
		if (waits.find())
		{
			handedOver(Integer.parseInt(waits.group(1)));
		}
		else if (text.contains(WAITS_WITH_LAST))
		{
			handedOver(1);
		}
		else if (text.contains(RETURNED_ALL))
		{
			handedOver(0);
		}
		else if (text.contains(SENT_BACK))
		{
			holding = 0;
		}
		if (text.contains(PAID_BY_HAND))
		{
			paidByHand = true;
		}
	}

	void gameMessage(String text)
	{
		if (text.startsWith(PAID_FROM_BAG))
		{
			tripsUntilPay = ServantType.TRIPS_PER_PAYMENT;
			if (type != null)
			{
				wagesPaid += type.getWage();
			}
			paidByHand = false;
			tickLog.add("wage paid from money bag");
		}
	}

	void clicked(NPC target)
	{
		returnDialogOpen = false;
		// Clicked away before he handed anything over: he keeps the whole fetch until you talk to him.
		if (awaitingHandOver && npc != null && target != npc)
		{
			awaitingHandOver = false;
			holding = Math.max(holding, requestedFetch > 0 ? requestedFetch : lastDelivery > 0 ? lastDelivery : type != null ? type.getCapacity() : 0);
			tickLog.add("hand-over skipped, butler holds " + holding);
		}
	}

	void dialogClosed()
	{
		returnDialogOpen = false;
	}

	void tick()
	{
		lastTickMillis = System.currentTimeMillis();
		readFetchOption();
	}

	boolean isNear(WorldPoint player)
	{
		return npc != null && npc.getWorldLocation().distanceTo(player) <= REACH;
	}

	boolean isAwaitingHandOver()
	{
		return awaitingHandOver && client.getTickCount() - arrivedTick <= HAND_OVER_TICKS;
	}

	// Measured trip once seen, else 0 so the policy uses the servant's known trip time.
	int tripTicks()
	{
		return Math.max(0, measuredTripTicks);
	}

	int ticksAway()
	{
		return npc != null || leftTick < 0 ? -1 : client.getTickCount() - leftTick;
	}

	// Ticks until he is back, or -1 while he is here or was never sent.
	int ticksLeft()
	{
		int away = ticksAway();
		if (away < 0 || type == null)
		{
			return -1;
		}
		int trip = measuredTripTicks > 0 ? measuredTripTicks : type.getTripTicks();
		// Far overdue means he is not on a bank trip (dismissed or left the house); stop counting.
		return away > trip + 10 ? -1 : Math.max(0, trip - away);
	}

	// Seconds until he is back, smoothed within the current tick; negative while he is here.
	double secondsLeft()
	{
		int ticks = ticksLeft();
		if (ticks < 0)
		{
			return -1;
		}
		long sinceTick = Math.min(600, System.currentTimeMillis() - lastTickMillis);
		return Math.max(0, ticks * 600 - sinceTick) / 1000.0;
	}

	private void handedOver(int stillHolding)
	{
		holding = stillHolding;
		awaitingHandOver = false;
		handOverTick = client.getTickCount();
	}

	// His options menu shows the real fetch amount.
	private void readFetchOption()
	{
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (options == null || options.isHidden() || options.getDynamicChildren() == null)
		{
			lastOptions = "";
			return;
		}
		StringBuilder all = new StringBuilder();
		for (Widget option : options.getDynamicChildren())
		{
			String text = Text.removeTags(option.getText());
			Matcher fetch = FETCH_OPTION.matcher(text);
			if (fetch.find())
			{
				requestedFetch = Integer.parseInt(fetch.group(1));
			}
			if (!text.isEmpty())
			{
				all.append(text).append(" / ");
			}
		}
		if (!all.toString().equals(lastOptions))
		{
			lastOptions = all.toString();
			tickLog.add("options " + lastOptions);
		}
	}
}

package com.constructionpilot;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("construction-pilot")
public interface ConstructionPilotConfig extends Config
{
	@ConfigSection(
		name = "Behaviour",
		description = "What the plugin does for you while you train in building mode",
		position = 0
	)
	String behaviourSection = "behaviour";

	@ConfigSection(
		name = "Butler",
		description = "When the plugin tells you to send the butler for more planks",
		position = 1
	)
	String butlerSection = "butler";

	@ConfigSection(
		name = "Highlights",
		description = "Colours and width of the outlines on the thing to click",
		position = 2
	)
	String highlightSection = "highlights";

	@ConfigSection(
		name = "Advanced",
		description = "Extra information for checking your speed and for troubleshooting",
		position = 3,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@ConfigItem(
		keyName = "smartLeftClick",
		name = "Smart left click",
		description = "Makes left click do the step that is due right now. When the butler should be sent, left clicking him talks to him even if he stands on a bench. When it is time to build or remove, left clicking the furniture or its space does that even if the butler is in the way. It only changes the order of the normal right click options, it never clicks for you. Recommended: on",
		position = 0,
		section = behaviourSection
	)
	default boolean smartLeftClick()
	{
		return true;
	}

	@ConfigItem(
		keyName = "setupHints",
		name = "Setup check",
		description = "Warns in orange when something you cannot build without is missing (a saw or a hammer). The box disappears once everything is in place",
		position = 1,
		section = behaviourSection
	)
	default boolean setupHints()
	{
		return true;
	}

	@ConfigItem(
		keyName = "setupTips",
		name = "Speed tips",
		description = "Adds optional grey tips to the setup box for the fastest hold 1 and click setup: the Construction QOL plugin with the right key (2 for oak larders, 6 for mahogany tables, 1 for teak garden benches, 2 for gnome benches), the demon butler, a servant's money bag and a fetch amount in whole builds (24 with 28 free slots). Below level 33 it suggests Mahogany Homes instead. Nothing is required: the plugin adapts to any servant, fetch amount and setup",
		position = 2,
		section = behaviourSection
	)
	default boolean setupTips()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPanel",
		name = "Show panel",
		description = "Shows a small box at the top left with the next step, your planks, where the butler is and how much this session cost. The outlines and the text above your character already tell you everything, so most players leave this off",
		position = 3,
		section = behaviourSection
	)
	default boolean showPanel()
	{
		return false;
	}

	@Range(min = 0, max = 28)
	@ConfigItem(
		keyName = "sendAtOverride",
		name = "Send butler at",
		description = "Leave at 0 to let the plugin work out the best moment: it looks at your free inventory slots, how many planks the butler brings and how fast you build, so he comes back just as you run low. Set a number to always send him once you hold that many planks or fewer instead",
		position = 0,
		section = butlerSection
	)
	default int sendAtOverride()
	{
		return 0;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "How thick the outline on the thing to click next is. The faint outline on the step after it always stays thin",
		position = 0,
		section = highlightSection
	)
	default int outlineWidth()
	{
		return 3;
	}

	@Alpha
	@ConfigItem(
		keyName = "buildColor",
		name = "Build color",
		description = "Colour of an empty space you should build on now. A faint version of it marks the space to build on right after",
		position = 1,
		section = highlightSection
	)
	default Color buildColor()
	{
		return new Color(0, 255, 0, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "removeColor",
		name = "Remove color",
		description = "Colour of furniture you should remove now, and of the countdown on one that is still appearing",
		position = 2,
		section = highlightSection
	)
	default Color removeColor()
	{
		return new Color(255, 80, 0, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "butlerColor",
		name = "Butler color",
		description = "Colour of the butler when you should talk to him (send him or take planks), and of the bell pull when you should ring for him. A faint version shows he is due right after your current build",
		position = 3,
		section = highlightSection
	)
	default Color butlerColor()
	{
		return new Color(0, 200, 255, 220);
	}

	@ConfigItem(
		keyName = "tickLog",
		name = "Tick log",
		description = "Writes every click, build, remove and butler trip with its game tick to the RuneLite client log. Only useful for measuring your timing or reporting a problem. Leave off otherwise",
		position = 0,
		section = advancedSection
	)
	default boolean tickLog()
	{
		return false;
	}
}

package com.constructionpilot;

import com.google.inject.Provides;
import java.util.List;
import javax.inject.Inject;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Menu;
import net.runelite.api.MenuEntry;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

// Routes game events to the trackers in a fixed order, then each tick turns their state into a Snapshot and
// asks Policy what to click. Overlays only draw the resulting Decision.
@PluginDescriptor(
	name = "Construction Pilot",
	description = "Shows what to build or remove next and when to send the butler: oak larders, mahogany tables, teak and gnome benches",
	tags = {"construction", "poh", "butler", "gnome bench", "mahogany table"}
)
public class ConstructionPilotPlugin extends Plugin
{
	private static final int INVENTORY_SIZE = 28;

	@Inject
	private Client client;
	@Inject
	private ConstructionPilotConfig config;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private ItemManager itemManager;
	@Inject
	private SceneOverlay sceneOverlay;
	@Inject
	private StatsPanel statsPanel;
	@Inject
	private SetupPanel setupPanel;
	@Inject
	private House house;
	@Inject
	private Butler butler;
	@Inject
	private BuildTimer buildTimer;
	@Inject
	private SetupCheck setupCheck;
	@Inject
	private TickLog tickLog;

	@Getter
	private Decision decision = Decision.IDLE;
	// Picked each tick from the space you stand at and the planks you carry.
	@Getter
	private Method method = Method.MAHOGANY_TABLE;
	@Getter
	private int planks;
	// Slots planks may use: everything except the other items you carry.
	@Getter
	private int plankSlots = INVENTORY_SIZE;
	private int freeSlots;
	@Getter
	private int planksUsed;
	@Getter
	private long planksCost;
	private String lastSwap = "";
	private int lastConstructionXp = -1;

	@Override
	protected void startUp()
	{
		overlayManager.add(sceneOverlay);
		overlayManager.add(statsPanel);
		overlayManager.add(setupPanel);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(sceneOverlay);
		overlayManager.remove(statsPanel);
		overlayManager.remove(setupPanel);
		reset();
	}

	private void reset()
	{
		house.reset();
		butler.reset();
		buildTimer.reset();
		decision = Decision.IDLE;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			reset();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (house.spawned(event.getGameObject()))
		{
			buildTimer.furnitureAppeared(event.getGameObject());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (house.despawned(event.getGameObject()))
		{
			buildTimer.furnitureGone(event.getGameObject());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		Player player = client.getLocalPlayer();
		butler.spawned(event.getNpc(), player != null ? player.getWorldLocation() : null);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		butler.despawned(event.getNpc());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}
		ItemContainer inventory = event.getItemContainer();
		int now = inventory.count(method.getPlank());
		if (now < planks)
		{
			planksUsed += planks - now;
			planksCost += (long) (planks - now) * itemManager.getItemPrice(method.getPlank());
			buildTimer.planksUsed(planks, now, method.getPlanksPerBuild());
		}
		else if (now > planks)
		{
			butler.planksGained(now - planks);
		}
		if (now != planks)
		{
			tickLog.add("planks " + planks + " -> " + now);
		}
		countSlots(inventory);
	}

	// Plank count and slots without treating the change as used or delivered planks.
	private void countSlots(ItemContainer inventory)
	{
		planks = inventory.count(method.getPlank());
		int used = 0;
		int plankStacks = 0;
		for (Item item : inventory.getItems())
		{
			if (item.getId() != -1 && item.getQuantity() > 0)
			{
				used++;
				if (item.getId() == method.getPlank())
				{
					plankStacks++;
				}
			}
		}
		plankSlots = INVENTORY_SIZE - (used - plankStacks);
		freeSlots = INVENTORY_SIZE - used;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			decision = Decision.IDLE;
			return;
		}
		butler.tick();
		buildTimer.tick();

		WorldPoint at = player.getWorldLocation();
		List<Spot> spots = house.spotsNear(at);
		pickMethod(spots);
		Snapshot.SnapshotBuilder builder = Snapshot.builder()
			.buildingMode(client.getVarbitValue(VarbitID.POH_BUILDING_MODE) == 1)
			.plankSlots(plankSlots)
			.freeSlots(freeSlots)
			.butlerPresent(butler.isNear(at))
			.butlerOnTrip(butler.getNpc() == null && butler.ticksLeft() >= 0)
			.butlerTile(butler.getNpc() != null ? butler.getNpc().getWorldLocation() : null)
			.butlerHolding(butler.getHolding())
			.awaitingHandOver(butler.isAwaitingHandOver())
			.servantType(butler.getType())
			.tripTicks(butler.tripTicks())
			.requestedFetch(butler.getRequestedFetch())
			.lastDelivery(butler.getLastDelivery())
			.sendAtOverride(config.sendAtOverride())
			.planksPerBuild(method.getPlanksPerBuild())
			.spots(spots);
		Snapshot snapshot = buildTimer.describe(builder, planks, method.getPlanksPerBuild()).build();

		Decision next = Policy.decide(snapshot);
		setupCheck.update(snapshot, method);
		if (tickLog.enabled())
		{
			tickLog.add("state " + next.getStep() + " " + method + " target=" + house.spaceAt(next.getTarget())
				+ " next=" + house.spaceAt(next.getNext()) + " planks=" + planks
				+ " butler=" + (butler.getNpc() != null ? "here holding " + butler.getHolding() : butler.ticksLeft() >= 0 ? "away " + butler.ticksLeft() : "none")
				+ " removing=" + snapshot.getRemoving() + " pending=" + buildTimer.isPending() + " countdown=" + next.getCountdown()
				+ String.format(" rate=%.2f trip=%d", buildTimer.getPlanksPerTick(), butler.tripTicks()));
			if (next.getStep() != decision.getStep())
			{
				tickLog.add("step " + next.getStep() + " (planks " + planks + ", send at " + next.getSendAt() + ", fetch " + next.getFetchAmount() + ")");
			}
		}
		decision = next;
	}

	private void pickMethod(List<Spot> spots)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (spots.isEmpty() || spots.get(0).getSpace() == null || inventory == null)
		{
			return;
		}
		Method picked = Method.at(spots.get(0).getSpace(), house.builtMethod(spots), method,
			inventory.count(ItemID.PLANK_TEAK), inventory.count(ItemID.PLANK_MAHOGANY), client.getBoostedSkillLevel(Skill.CONSTRUCTION));
		if (picked != method)
		{
			tickLog.add("method " + method + " -> " + picked);
			method = picked;
			countSlots(inventory);
		}
	}

	// Lowest priority runs last, after Menu Entry Swapper and other swappers, so this choice is the final one.
	@Subscribe(priority = -100)
	public void onPostMenuSort(PostMenuSort event)
	{
		if (!config.smartLeftClick() || client.isMenuOpen())
		{
			return;
		}
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		MenuEntry promoted = SmartLeftClick.promote(entries, decision.getStep());
		if (promoted == null)
		{
			return;
		}
		menu.setMenuEntries(entries);
		String swapped = Text.removeTags(promoted.getOption()) + " " + Text.removeTags(promoted.getTarget()).toLowerCase();
		if (!swapped.equals(lastSwap))
		{
			lastSwap = swapped;
			tickLog.add("left click -> " + swapped);
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		tickLog.add("click " + event.getMenuOption() + " | " + event.getMenuTarget() + " | " + event.getMenuAction());
		butler.clicked(event.getMenuEntry().getNpc());
		String option = event.getMenuOption();
		WorldPoint tile = null;
		if ("Build".equals(option) || "Remove".equals(option))
		{
			WorldView view = client.getTopLevelWorldView();
			tile = WorldPoint.fromScene(view, event.getParam0(), event.getParam1(), view.getPlane());
		}
		buildTimer.clicked(option, tile);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.CHAT_LEFT)
		{
			butler.dialogClosed();
		}
		if (event.getGroupId() == InterfaceID.POH_FURNITURE_CREATION)
		{
			buildTimer.buildMenuClosed(planks);
		}
		tickLog.add("interface closes " + event.getGroupId());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.DIALOG)
		{
			String text = Text.sanitizeMultilineText(event.getMessage());
			butler.dialog(text);
			tickLog.add("dialog " + text);
		}
		else if (event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			butler.gameMessage(Text.removeTags(event.getMessage()));
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.CONSTRUCTION)
		{
			return;
		}
		if (lastConstructionXp >= 0 && event.getXp() > lastConstructionXp)
		{
			tickLog.add("xp +" + (event.getXp() - lastConstructionXp) + " total " + event.getXp());
		}
		lastConstructionXp = event.getXp();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			tickLog.add("player animation " + event.getActor().getAnimation());
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		tickLog.add("interface opens " + event.getGroupId());
	}

	@Provides
	ConstructionPilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ConstructionPilotConfig.class);
	}
}

package com.constructionpilot;

import java.util.List;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

// What to click now, and faintly what comes right after, so the mouse can already move there.
@Value
@Builder(toBuilder = true)
class Decision
{
	static final Decision IDLE = Decision.builder().step(Step.IDLE).build();

	Step step;
	// Tiles of the space to click for BUILD or REMOVE (both halves of a garden bench); null otherwise.
	List<WorldPoint> target;
	int fetchAmount;
	int sendAt;
	// For REMOVE_SOON: ticks until the furniture being built appears and can be removed.
	int countdown;
	// The bench action right after this step (the build after a remove, or the bench after a butler step).
	List<WorldPoint> next;
	Step nextStep;
	// After this build the butler is due: show him faintly so the mouse can get there early.
	boolean butlerNext;
}

package com.constructionpilot;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;

// The build spaces, the furniture on them and the bell-pull, kept from spawn events instead of scene scans.
@Singleton
class House
{
	// Build space of each hotspot; a garden seating space is two hotspots, one per bench half.
	private static final Map<Integer, String> HOTSPOT_KEYS = Map.of(
		ObjectID.POH_DINING_ROOM_1, "table",
		ObjectID.POH_KITCHEN_5, "larder",
		ObjectID.POH_SUPERIOR_GARDEN_HOTSPOT_SEATING_A_LEFT, "garden A",
		ObjectID.POH_SUPERIOR_GARDEN_HOTSPOT_SEATING_A_RIGHT, "garden A",
		ObjectID.POH_SUPERIOR_GARDEN_HOTSPOT_SEATING_B_LEFT, "garden B",
		ObjectID.POH_SUPERIOR_GARDEN_HOTSPOT_SEATING_B_RIGHT, "garden B"
	);
	private static final Map<String, Space> KEY_SPACES = Map.of(
		"table", Space.TABLE,
		"larder", Space.LARDER,
		"garden A", Space.GARDEN,
		"garden B", Space.GARDEN
	);
	private static final Set<Integer> BELL_PULLS = Set.of(ObjectID.POH_BELLPULL_1, ObjectID.POH_BELLPULL_2, ObjectID.POH_BELLPULL_3);
	// The dining room and the superior garden can both be loaded; only spaces next to the player count.
	private static final int REACH = 3;

	private final TickLog tickLog;
	private final List<GameObject> hotspots = new ArrayList<>();
	private final List<GameObject> furniture = new ArrayList<>();
	// Which build space each hotspot tile belongs to, so the furniture built there groups with it.
	private final Map<WorldPoint, String> tileSpace = new HashMap<>();
	// Furniture seen on a tile whose hotspot never showed: its method tells the kind of space.
	private final Map<String, Space> seenSpaces = new HashMap<>();

	@Getter
	private GameObject bellPull;

	@Inject
	House(TickLog tickLog)
	{
		this.tickLog = tickLog;
	}

	void reset()
	{
		hotspots.clear();
		furniture.clear();
		bellPull = null;
	}

	// True when furniture appeared.
	boolean spawned(GameObject object)
	{
		int id = object.getId();
		if (BELL_PULLS.contains(id))
		{
			bellPull = object;
		}
		if (HOTSPOT_KEYS.containsKey(id))
		{
			hotspots.add(object);
			tileSpace.put(object.getWorldLocation(), HOTSPOT_KEYS.get(id));
			tickLog.add("hotspot appears " + id + " at " + object.getWorldLocation());
		}
		else if (Method.ALL_FURNITURE.contains(id))
		{
			furniture.add(object);
			seenSpaces.putIfAbsent(spaceAt(object.getWorldLocation()), Method.ofFurniture(id).getSpace());
			tickLog.add("furniture appears " + id + " at " + object.getWorldLocation());
			return true;
		}
		return false;
	}

	// True when furniture went away.
	boolean despawned(GameObject object)
	{
		if (object == bellPull)
		{
			bellPull = null;
		}
		if (hotspots.remove(object))
		{
			tickLog.add("hotspot gone " + object.getId());
		}
		if (furniture.remove(object))
		{
			tickLog.add("furniture gone " + object.getId());
			return true;
		}
		return false;
	}

	// The space a tile belongs to; a tile never seen empty is its own space.
	String spaceAt(WorldPoint tile)
	{
		return tileSpace.getOrDefault(tile, tile.toString());
	}

	String spaceAt(List<WorldPoint> tiles)
	{
		return tiles == null || tiles.isEmpty() ? "-" : spaceAt(tiles.get(0));
	}

	boolean isSpace(WorldPoint tile)
	{
		return tileSpace.containsKey(tile);
	}

	// Spaces within reach of the player, nearest first, with both halves of a garden bench grouped.
	List<Spot> spotsNear(WorldPoint at)
	{
		Map<String, List<WorldPoint>> tiles = new LinkedHashMap<>();
		Map<String, Boolean> built = new HashMap<>();
		List<GameObject> all = new ArrayList<>(furniture);
		all.addAll(hotspots);
		for (GameObject object : all)
		{
			WorldPoint tile = object.getWorldLocation();
			if (tile.distanceTo(at) > REACH)
			{
				continue;
			}
			String key = spaceAt(tile);
			tiles.computeIfAbsent(key, k -> new ArrayList<>()).add(tile);
			built.merge(key, Method.ALL_FURNITURE.contains(object.getId()), Boolean::logicalOr);
		}
		List<Spot> spots = new ArrayList<>();
		for (Map.Entry<String, List<WorldPoint>> entry : tiles.entrySet())
		{
			String key = entry.getKey();
			spots.add(new Spot(key, entry.getValue(), built.get(key), KEY_SPACES.getOrDefault(key, seenSpaces.get(key))));
		}
		spots.sort(Comparator.comparingInt(spot -> spot.getTiles().get(0).distanceTo(at)));
		return spots;
	}

	// The method of furniture standing in one of these spaces, or null when all are empty.
	Method builtMethod(List<Spot> spots)
	{
		for (GameObject object : furniture)
		{
			for (Spot spot : spots)
			{
				if (spot.getTiles().contains(object.getWorldLocation()))
				{
					return Method.ofFurniture(object.getId());
				}
			}
		}
		return null;
	}

	// All tiles of the space containing this tile, or null when it is not a space near the player.
	List<WorldPoint> spaceTiles(WorldPoint tile, WorldPoint player)
	{
		if (tile == null || player == null)
		{
			return null;
		}
		for (Spot spot : spotsNear(player))
		{
			if (spot.getTiles().contains(tile))
			{
				return spot.getTiles();
			}
		}
		return null;
	}

	// Looked up each frame, so a replaced table or hotspot is never stale.
	List<GameObject> objectsAt(List<WorldPoint> spotTiles)
	{
		List<GameObject> result = within(furniture, spotTiles);
		return result.isEmpty() ? within(hotspots, spotTiles) : result;
	}

	private static List<GameObject> within(List<GameObject> objects, List<WorldPoint> tiles)
	{
		List<GameObject> result = new ArrayList<>();
		for (GameObject object : objects)
		{
			if (tiles.contains(object.getWorldLocation()))
			{
				result.add(object);
			}
		}
		return result;
	}
}

package com.constructionpilot;

import java.util.HashSet;
import java.util.Set;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.ObjectID;

// The training methods this plugin drives (wiki: Construction training). Build menu keys are for Construction QOL.
@Getter
@RequiredArgsConstructor
enum Method
{
	OAK_LARDER("oak larders", Space.LARDER, ItemID.PLANK_OAK, 8, 33, "2", "oak larder",
		Set.of(ObjectID.POH_LARDER_2)),
	MAHOGANY_TABLE("mahogany tables", Space.TABLE, ItemID.PLANK_MAHOGANY, 6, 52, "6", "mahogany table",
		Set.of(ObjectID.POH_DININGTABLE_6)),
	TEAK_GARDEN_BENCH("teak garden benches", Space.GARDEN, ItemID.PLANK_TEAK, 6, 66, "1", "teak garden bench",
		Set.of(ObjectID.POH_GARDEN_BENCH_TEAK_LEFT, ObjectID.POH_GARDEN_BENCH_TEAK_RIGHT)),
	GNOME_BENCH("gnome benches", Space.GARDEN, ItemID.PLANK_MAHOGANY, 6, 77, "2", "gnome bench",
		Set.of(ObjectID.POH_GARDEN_BENCH_GNOME_LEFT, ObjectID.POH_GARDEN_BENCH_GNOME_RIGHT));

	static final Set<Integer> ALL_FURNITURE = new HashSet<>();
	static final int FIRST_LEVEL = OAK_LARDER.level;

	static
	{
		for (Method method : values())
		{
			ALL_FURNITURE.addAll(method.furniture);
		}
	}

	private final String name;
	private final Space space;
	private final int plank;
	private final int planksPerBuild;
	private final int level;
	private final String qolKey;
	// Menu target of the built furniture's Remove option, lower case.
	private final String furnitureName;
	private final Set<Integer> furniture;

	static Method ofFurniture(int objectId)
	{
		for (Method method : values())
		{
			if (method.furniture.contains(objectId))
			{
				return method;
			}
		}
		return null;
	}

	// The garden takes either bench: go by the furniture standing there, else by the planks you carry, else stay
	// with the current bench (out of planks while the butler is away), else by level.
	static Method at(Space space, Method built, Method current, int teakPlanks, int mahoganyPlanks, int level)
	{
		if (built != null && built.space == space)
		{
			return built;
		}
		switch (space)
		{
			case LARDER:
				return OAK_LARDER;
			case TABLE:
				return MAHOGANY_TABLE;
			default:
				if (teakPlanks != mahoganyPlanks)
				{
					return teakPlanks > mahoganyPlanks ? TEAK_GARDEN_BENCH : GNOME_BENCH;
				}
				if (current.space == Space.GARDEN)
				{
					return current;
				}
				return level >= GNOME_BENCH.level ? GNOME_BENCH : TEAK_GARDEN_BENCH;
		}
	}
}

package com.constructionpilot;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

final class Policy
{
	private static final int DEFAULT_TRIP_TICKS = 12;
	// Talking to the servant and choosing the fetch takes a couple of ticks on top of the trip.
	static final int DIALOG_TICKS = 2;
	// Remove click to the space being free again, from the tick logs (click, gone one tick later).
	static final int REMOVE_TICKS = 2;

	private Policy()
	{
	}

	static Decision decide(Snapshot s)
	{
		List<Spot> spots = s.getSpots();
		if (!s.isBuildingMode() || spots == null || spots.isEmpty())
		{
			return Decision.IDLE;
		}

		int fetch = fetchAmount(s);
		int sendAt = sendAt(s, fetch);
		int planks = s.getPlanks();
		int holding = s.getButlerHolding();
		int perBuild = s.getPlanksPerBuild();

		// Back but not handed over yet (you were busy): he has your planks, so he is next, or now when you are out.
		boolean waitingOnHim = s.isButlerPresent() && s.isAwaitingHandOver();
		boolean handedOver = s.isButlerPresent() && !s.isAwaitingHandOver();
		// One more build and he is due: planks after it at or under the send point.
		boolean butlerNext = waitingOnHim || handedOver && (holding > 0
			|| (planks >= perBuild && planks - perBuild <= sendAt));
		Decision bench = benchDecision(s, spots, butlerNext);

		// Take only when it is worth a click: everything he holds fits, or the next build needs planks.
		boolean allFit = s.getFreeSlots() >= holding;
		// Also send when you would run dry before he is back: a few planks he has to hold cost one take click,
		// waiting with nothing to build costs his whole trip.
		boolean runsDry = s.getSendAtOverride() == 0 && planks - usedDuringTrip(s) < perBuild;
		boolean wantsTake = holding > 0 && (allFit || planks < perBuild);
		boolean wantsSend = holding == 0 && (planks <= sendAt || runsDry);

		Step butlerStep = null;
		if (waitingOnHim && planks < perBuild)
		{
			butlerStep = Step.TAKE_PLANKS;
		}
		// Needed now but neither here nor on a trip: he wandered off, so ring for him.
		else if (!s.isButlerPresent() && !s.isButlerOnTrip() && s.getServantType() != null && (wantsTake || wantsSend))
		{
			butlerStep = Step.CALL_BUTLER;
		}
		else if (handedOver && holding > 0 && (allFit || (planks < perBuild && s.getFreeSlots() > 0)))
		{
			butlerStep = Step.TAKE_PLANKS;
		}
		else if (handedOver && wantsSend)
		{
			butlerStep = Step.SEND_BUTLER;
		}

		if (butlerStep == null)
		{
			return bench.toBuilder().fetchAmount(fetch).sendAt(sendAt).build();
		}
		// The bench action that follows stays visible, faintly, while the butler is the current step.
		boolean benchQueued = bench.getTarget() != null && bench.getStep() != Step.WAIT;
		return Decision.builder()
			.step(butlerStep)
			.fetchAmount(fetch)
			.sendAt(sendAt)
			.next(benchQueued ? bench.getTarget() : null)
			.nextStep(benchQueued ? bench.getStep() : null)
			.build();
	}

	private static Decision benchDecision(Snapshot s, List<Spot> spots, boolean butlerNext)
	{
		// Waiting for the bench or table to appear: count down so the remove lands on the tick it shows up.
		if (s.getPendingBuild() != null)
		{
			return Decision.builder().step(Step.REMOVE_SOON).target(s.getPendingBuild()).countdown(Math.max(0, s.getTicksUntilBuilt())).build();
		}
		// A remove already clicked counts as done: the build click on the other side can follow on the next tick.
		if (s.getRemoving() != null)
		{
			List<Spot> after = new ArrayList<>();
			for (Spot spot : spots)
			{
				after.add(spot.getKey().equals(s.getRemoving()) ? new Spot(spot.getKey(), spot.getTiles(), false, spot.getSpace()) : spot);
			}
			spots = after;
		}
		// Light up every space that can take the action: built ones to remove, else empty ones to build.
		List<WorldPoint> built = notUnderButler(spots, true, s.getButlerTile());
		if (!built.isEmpty())
		{
			List<WorldPoint> empty = tiles(spots, false);
			boolean canBuildNext = !empty.isEmpty() && s.getPlanks() >= s.getPlanksPerBuild();
			return Decision.builder()
				.step(Step.REMOVE)
				.target(built)
				.next(canBuildNext ? empty : null)
				.nextStep(canBuildNext ? Step.BUILD : null)
				.butlerNext(butlerNext && s.getButlerHolding() > 0)
				.build();
		}
		if (s.getPlanks() >= s.getPlanksPerBuild())
		{
			String justCleared = s.getRemoving() != null ? s.getRemoving() : s.getFreshRemoved();
			return Decision.builder().step(Step.BUILD).target(buildTarget(spots, justCleared, s.getButlerTile())).butlerNext(butlerNext).build();
		}
		return Decision.builder().step(Step.WAIT).build();
	}

	static int fetchAmount(Snapshot s)
	{
		int capacity = s.getServantType() != null ? s.getServantType().getCapacity() : s.getPlankSlots();
		int requested = s.getRequestedFetch() > 0 ? s.getRequestedFetch()
			: s.getLastDelivery() > 0 ? s.getLastDelivery() + s.getButlerHolding()
			: capacity;
		return Math.min(Math.min(requested, capacity), s.getPlankSlots());
	}

	private static int tripTicks(Snapshot s)
	{
		return s.getTripTicks() > 0 ? s.getTripTicks() : s.getServantType() != null ? s.getServantType().getTripTicks() : DEFAULT_TRIP_TICKS;
	}

	// Send so the delivery fits on arrival: the planks left by then plus the fetch must not exceed the slots.
	static int sendAt(Snapshot s, int fetch)
	{
		if (s.getSendAtOverride() > 0)
		{
			return s.getSendAtOverride();
		}
		return Math.max(0, Math.min(s.getPlankSlots(), s.getPlankSlots() - fetch + usedDuringTrip(s)));
	}

	// Walks the remove/build cycle from the current state over the trip: built furniture has to come off
	// before planks are used again, so a send right after building lets fewer planks go than the average rate.
	static int usedDuringTrip(Snapshot s)
	{
		int perBuild = s.getPlanksPerBuild();
		int horizon = tripTicks(s) + DIALOG_TICKS;
		double ticksPerBuild = s.getPlanksPerTick() > 0 ? perBuild / s.getPlanksPerTick() : perBuild;
		int buildTicks = Math.max(2, (int) Math.round(ticksPerBuild) - REMOVE_TICKS);
		int built = 0;
		if (s.getSpots() != null)
		{
			for (Spot spot : s.getSpots())
			{
				if (spot.isBuilt() || (s.getPendingBuild() != null && spot.getTiles().containsAll(s.getPendingBuild())))
				{
					built++;
				}
			}
		}
		int planks = s.getPlanks();
		int used = 0;
		// A bench still appearing finishes while you talk to him, so its wait overlaps the dialog ticks.
		int tick = 0;
		while (true)
		{
			if (built > 0)
			{
				tick += REMOVE_TICKS;
				if (tick > horizon)
				{
					break;
				}
				built--;
				continue;
			}
			if (planks < perBuild)
			{
				break;
			}
			tick += buildTicks;
			if (tick > horizon)
			{
				break;
			}
			planks -= perBuild;
			used += perBuild;
			built++;
		}
		return used;
	}

	// Right after a remove the tick-optimal build is the other side; once the rhythm lapsed any empty space
	// will do, except one the butler stands on.
	private static List<WorldPoint> buildTarget(List<Spot> spots, String freshRemoved, WorldPoint butlerTile)
	{
		if (freshRemoved != null)
		{
			List<WorldPoint> other = new ArrayList<>();
			for (Spot spot : spots)
			{
				if (!spot.isBuilt() && !spot.getKey().equals(freshRemoved))
				{
					other.addAll(spot.getTiles());
				}
			}
			if (!other.isEmpty())
			{
				return other;
			}
		}
		return notUnderButler(spots, false, butlerTile);
	}

	// All spaces in the given state, minus the one under the butler unless that would leave none.
	private static List<WorldPoint> notUnderButler(List<Spot> spots, boolean built, WorldPoint butlerTile)
	{
		List<WorldPoint> all = tiles(spots, built);
		if (butlerTile == null)
		{
			return all;
		}
		List<WorldPoint> free = new ArrayList<>();
		for (Spot spot : spots)
		{
			if (spot.isBuilt() == built && !spot.getTiles().contains(butlerTile))
			{
				free.addAll(spot.getTiles());
			}
		}
		return free.isEmpty() ? all : free;
	}

	private static List<WorldPoint> tiles(List<Spot> spots, boolean built)
	{
		List<WorldPoint> result = new ArrayList<>();
		for (Spot spot : spots)
		{
			if (spot.isBuilt() == built)
			{
				result.addAll(spot.getTiles());
			}
		}
		return result;
	}
}

package com.constructionpilot;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

// Median of the last few samples, so one slow trip or a pause does not swing the estimate.
class RollingMedian
{
	private final int size;
	private final Deque<Integer> window = new ArrayDeque<>();

	RollingMedian(int size)
	{
		this.size = size;
	}

	int add(int sample)
	{
		window.addLast(sample);
		if (window.size() > size)
		{
			window.removeFirst();
		}
		List<Integer> sorted = new ArrayList<>(window);
		sorted.sort(null);
		return sorted.get(sorted.size() / 2);
	}

	void clear()
	{
		window.clear();
	}
}

package com.constructionpilot;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class SceneOverlay extends Overlay
{
	// Alpha of the thin outline on what comes after the current step.
	private static final int FAINT_ALPHA = 70;

	private final Client client;
	private final ConstructionPilotPlugin plugin;
	private final House house;
	private final Butler butler;
	private final ConstructionPilotConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	SceneOverlay(Client client, ConstructionPilotPlugin plugin, House house, Butler butler, ConstructionPilotConfig config, ModelOutlineRenderer outlines)
	{
		this.client = client;
		this.plugin = plugin;
		this.house = house;
		this.butler = butler;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Decision decision = plugin.getDecision();
		Step step = decision.getStep();
		if (step == Step.IDLE)
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player != null)
		{
			String text = butler.isReturnDialogOpen()
				? "Don't continue, click the " + (step == Step.REMOVE || step == Step.REMOVE_SOON ? "furniture" : "next spot")
				: playerLabel(step, butler.secondsLeft());
			label(graphics, player.getCanvasTextLocation(graphics, text, player.getLogicalHeight() + 40), text, Color.WHITE);
		}

		drawNext(graphics, decision);

		if (step == Step.CALL_BUTLER)
		{
			GameObject bell = house.getBellPull();
			if (bell != null)
			{
				outlines.drawOutline(bell, config.outlineWidth(), config.butlerColor(), 2);
				label(graphics, bell.getCanvasTextLocation(graphics, "Ring", 120), "Ring", config.butlerColor());
			}
			return null;
		}

		NPC servant = butler.getNpc();
		if (servant != null)
		{
			String text = butlerLabel(decision, butler.getHolding());
			boolean act = step == Step.SEND_BUTLER || step == Step.TAKE_PLANKS;
			if (act)
			{
				outlines.drawOutline(servant, config.outlineWidth(), config.butlerColor(), 2);
			}
			else if (decision.isButlerNext())
			{
				outlines.drawOutline(servant, 1, faint(config.butlerColor()), 4);
				if (text == null)
				{
					text = "next";
				}
			}
			if (text != null)
			{
				label(graphics, servant.getCanvasTextLocation(graphics, text, servant.getLogicalHeight() + 40), text, config.butlerColor());
			}
			if (act)
			{
				return null;
			}
		}

		if (decision.getTarget() == null)
		{
			return null;
		}
		List<GameObject> targets = house.objectsAt(decision.getTarget());
		if (targets.isEmpty())
		{
			return null;
		}

		Color color = step == Step.BUILD ? config.buildColor() : config.removeColor();
		String text = step == Step.REMOVE_SOON ? countdownLabel(decision.getCountdown()) : step.getLabel();
		for (GameObject target : targets)
		{
			outlines.drawOutline(target, config.outlineWidth(), color, 2);
		}
		GameObject first = targets.get(0);
		label(graphics, first.getCanvasTextLocation(graphics, text, 120), text, color);
		return null;
	}

	// Faint and thin so it never reads as the current step; coloured by what it is for.
	private void drawNext(Graphics2D graphics, Decision decision)
	{
		if (decision.getNext() == null)
		{
			return;
		}
		boolean remove = decision.getNextStep() == Step.REMOVE || decision.getNextStep() == Step.REMOVE_SOON;
		Color color = faint(remove ? config.removeColor() : config.buildColor());
		List<GameObject> nextTargets = house.objectsAt(decision.getNext());
		for (GameObject next : nextTargets)
		{
			outlines.drawOutline(next, 1, color, 4);
		}
		if (!nextTargets.isEmpty())
		{
			label(graphics, nextTargets.get(0).getCanvasTextLocation(graphics, "next", 60), "next", Color.GRAY);
		}
	}

	private static String countdownLabel(int ticks)
	{
		return ticks <= 0 ? "Remove NOW" : "Remove in " + ticks;
	}

	// While the butler is out, count his trip down on the player's head.
	private static String playerLabel(Step step, double butlerSecondsLeft)
	{
		String base = step == Step.REMOVE_SOON ? "Get ready"
			: step == Step.CALL_BUTLER ? "Call butler (bell or house options)"
			: step.getLabel();
		if (butlerSecondsLeft < 0)
		{
			return base;
		}
		String countdown = String.format("Butler %.1fs", butlerSecondsLeft);
		return step == Step.WAIT ? countdown : base + "  (" + countdown + ")";
	}

	// One label per butler, so nothing stacks when zoomed out.
	private static String butlerLabel(Decision decision, int holding)
	{
		Step step = decision.getStep();
		if (step == Step.TAKE_PLANKS)
		{
			return holding > 0 ? "Take " + holding + " planks" : step.getLabel();
		}
		if (step == Step.SEND_BUTLER)
		{
			return step.getLabel();
		}
		return holding > 0 ? "Holding " + holding : null;
	}

	private static Color faint(Color color)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), FAINT_ALPHA);
	}

	private static void label(Graphics2D graphics, Point at, String text, Color color)
	{
		if (at != null)
		{
			OverlayUtil.renderTextLocation(graphics, at, text, color);
		}
	}
}

